INSERT INTO NOTIFICATION( /* WebSocketMapper.saveNotification (알림 저장) */
                          RECEIVER_ID
                        , SENDER_ID
                        , NOTI_TYPE
                        , MESSAGE
                        , IS_READ
                        , REG_DATE
                        , TARGET_URL
)    VALUES (
              #{receiverId}
            , #{senderId}
            , #{notiType}
            , #{message}
            , #{isRead}
            , #{regDate}
            , #{targetUrl}
            )
